INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Ausbildungsplan immer gesetzlich vorgeschrieben?', 2, '[{"text": "Nein", "correct": true, "because": "Flexibel, aber oft empfohlen"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend gesetzlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Ausbildungsplan?', 3, '[{"text": "Strukturierte Kompetenzvermittlung", "correct": true, "because": "Definiert Lernschritte"}, {"text": "Kosten senken", "correct": false, "because": "Indirekter Effekt"}, {"text": "Design verbessern", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Ausbildungsplan?', 5, '[{"text": "Lernziele", "correct": true, "because": "Definiert Ausbildungsinhalte"}, {"text": "Zeitplan", "correct": true, "because": "Legt Dauer fest"}, {"text": "Marketingstrategie", "correct": false, "because": "Kein Ausbildungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Ausbildungsplan strukturiert die Ausbildung. b) Er ist immer starr.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Flexibilität möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Ausbildungsplan?', 4, '[{"text": "Lerninhalte", "correct": false, "because": "Kern der Planung"}, {"text": "Zeitliche Abfolge", "correct": false, "because": "Struktur wichtig"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Ausbildungsplan Meilensteine enthält?', 2, '[{"text": "Ja", "correct": true, "because": "Markiert Fortschritte"}, {"text": "Nein", "correct": false, "because": "Häufig enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für einen Ausbildungsplan entscheidend?', 3, '[{"text": "Zeitplan", "correct": true, "because": "Legt Ablauf fest"}, {"text": "Dekoration", "correct": false, "because": "Kein Bezug"}, {"text": "Werbekampagne", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Erstellung eines Ausbildungsplans?', 5, '[{"text": "Festlegung von Lernzielen", "correct": true, "because": "Definiert Inhalte"}, {"text": "Zeitliche Einteilung", "correct": true, "because": "Strukturiert Ablauf"}, {"text": "Produktwerbung", "correct": false, "because": "Kein Ausbildungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Ausbildungsplan hilft bei der Koordination. b) Er ist nur für große Firmen nötig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für kleine Firmen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Ausbildungsplan unwichtig?', 4, '[{"text": "Lerninhalte", "correct": false, "because": "Kern der Planung"}, {"text": "Zeitplan", "correct": false, "because": "Struktur entscheidend"}, {"text": "Bürofarben", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Ausbildungsplan flexibel?', 2, '[{"text": "Ja", "correct": true, "because": "Anpassbar an Bedarf"}, {"text": "Nein", "correct": false, "because": "Nicht statisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt ein Ausbildungsplan?', 4, '[{"text": "Klare Struktur", "correct": true, "because": "Übersicht verbessert"}, {"text": "Effiziente Ausbildung", "correct": true, "because": "Zeit optimiert"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Ausbildungsplan nur für Auszubildende ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Ausbilder"}, {"text": "Ja", "correct": false, "because": "Beidseitig nützlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Ausbildungsplan?', 3, '[{"text": "Lernziele", "correct": true, "because": "Definiert Inhalte"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Ausbildungsplan legt Zeitrahmen fest. b) Er ist nur für praktische Inhalte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Theorie enthalten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein schlechter Ausbildungsplan?', 5, '[{"text": "Unklare Ziele", "correct": true, "because": "Fehlende Struktur"}, {"text": "Ineffiziente Ausbildung", "correct": true, "because": "Zeitverlust"}, {"text": "Hohe Flexibilität", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Ausbildungsplan unwichtig?', 3, '[{"text": "Zeitplan", "correct": false, "because": "Struktur entscheidend"}, {"text": "Lerninhalte", "correct": false, "because": "Kern der Planung"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Ausbildungsplan angepasst werden?', 3, '[{"text": "Ja", "correct": true, "because": "Flexibel bei Bedarf"}, {"text": "Nein", "correct": false, "because": "Nicht statisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Ausbildungsplan rechtliche Vorgaben erfüllen muss?', 2, '[{"text": "Ja", "correct": true, "because": "Berufsordnung beachten"}, {"text": "Nein", "correct": false, "because": "Teilweise vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für einen effektiven Ausbildungsplan?', 4, '[{"text": "Zeitliche Meilensteine", "correct": true, "because": "Markiert Fortschritte"}, {"text": "Dekoration", "correct": false, "because": "Kein Bezug"}, {"text": "Werbekampagne", "correct": false, "because": "Anderer Bereich"}]');
